var building = new Building(name, color, height, length, width, x, y, z, areaId);
Assert.That(building.Name, Is.EqualTo(name));
Assert.That(building.Color, Is.EqualTo(color));
Assert.That(building.Height, Is.EqualTo(height));
Assert.That(building.Length, Is.EqualTo(length));
Assert.That(building.Width, Is.EqualTo(width));
Assert.That(building.X, Is.EqualTo(x));
Assert.That(building.Y, Is.EqualTo(y));
Assert.That(building.Z, Is.EqualTo(z));
Assert.That(building.AreaId, Is.EqualTo(areaId));

var ex = Assert.Throws<ArgumentException>(() => 
    new Building(name!, color, height, length, width, x, y, z, areaId));
Assert.That(ex.ParamName, Is.EqualTo("name"));

var ex = Assert.Throws<ArgumentException>(() => 
    new Building(name, color, height, length, width, x, y, z, areaId));
Assert.That(ex.ParamName, Is.EqualTo("name"));

var ex = Assert.Throws<ArgumentException>(() => 
    new Building(name, color!, height, length, width, x, y, z, areaId));
Assert.That(ex.ParamName, Is.EqualTo("color"));

var ex = Assert.Throws<ArgumentException>(() => 
    new Building(name, color, height, length, width, x, y, z, areaId));
Assert.That(ex.ParamName, Is.EqualTo("height"));

var ex = Assert.Throws<ArgumentException>(() => 
    new Building(name, color, height, length, width, x, y, z, areaId));
Assert.That(ex.ParamName, Is.EqualTo("length"));

var ex = Assert.Throws<ArgumentException>(() => 
    new Building(name, color, height, length, width, x, y, z, areaId));
Assert.That(ex.ParamName, Is.EqualTo("width"));

var ex = Assert.Throws<ArgumentException>(() => 
    new Building(name, color, height, length, width, x, y, z, areaId));
Assert.That(ex.ParamName, Is.EqualTo("areaId"));

var building = new Building(name, color, height, length, width, x, y, z, areaId);
Assert.That(building.Height, Is.EqualTo(height));
Assert.That(building.Length, Is.EqualTo(length));
Assert.That(building.Width, Is.EqualTo(width));

var result = await service.AddBuildingAsync(building);
Assert.That(result, Is.Not.Null);
Assert.That(result.Name, Is.EqualTo(building.Name));
mockRepository.Verify(r => r.AddAsync(building), Times.Once);

var ex = Assert.ThrowsAsync<DuplicateBuildingException>(() => 
    service.AddBuildingAsync(building));
Assert.That(ex.Message, Contains.Substring("Building with name 'Engineering Building' already exists"));
mockRepository.Verify(r => r.AddAsync(It.IsAny<Building>()), Times.Never);

var ex = Assert.ThrowsAsync<AreaNotFoundException>(() => 
    service.AddBuildingAsync(building));
mockRepository.Verify(r => r.AddAsync(It.IsAny<Building>()), Times.Never);

var result = await repository.AddAsync(building);
Assert.That(result, Is.Not.Null);
mockDbSet.Verify(d => d.AddAsync(building, It.IsAny<CancellationToken>()), Times.Once);
mockDbContext.Verify(c => c.SaveChangesAsync(It.IsAny<CancellationToken>()), Times.Once);

var result = await AddBuildingHandler.HandleAsync(request, mockService.Object);
Assert.That(result, Is.TypeOf<Created<AddBuildingResponse>>());
var createdResult = (Created<AddBuildingResponse>)result;
Assert.That(createdResult.Value.Building.Name, Is.EqualTo(request.Name));

var result = await AddBuildingHandler.HandleAsync(request, mockService.Object);
Assert.That(result, Is.TypeOf<Conflict<string>>());
var conflictResult = (Conflict<string>)result;
Assert.That(conflictResult.Value, Contains.Substring("already exists"));

var result = await AddBuildingHandler.HandleAsync(request, mockService.Object);
Assert.That(result, Is.TypeOf<BadRequest<string>>());
var badRequestResult = (BadRequest<string>)result;
Assert.That(badRequestResult.Value, Contains.Substring("cannot be empty"));
